def reverse_books(head):
    if not head:
        return None
    stack = []
    current = head
    while current:
        stack.append(current)
        current = current.next
    new_head = stack.pop()
    current = new_head
    while stack:
        current.next = stack.pop()
        current = current.next
    current.next = None
    return new_head

